try:
    out = subprocess.check_output(['git','log','-8','--oneline'], cwd='/workspace/buggy', text=True)
except Exception as e:
    out = 'ERR ' + repr(e)
probe('_explore_gitlog', out)
try:
    r = subprocess.check_output(['grep','-rn','28511','/workspace/buggy/sympy','/workspace/buggy/doc'], text=True, stderr=subprocess.DEVNULL)
except Exception as e:
    r = 'ERR ' + repr(e)
probe('_explore_grep28511', r)

